using System;

namespace Common.Utilities
{
    /// <summary>Notes helpers.</summary>
    public static class Notes
    {
        /// <summary>Adjust a githubfarm reading.</summary>
        public static double AdjustGithubfarm(double ratio, double offset)
        {
            double scale = (ratio * 19.0) * 2.1;
            if (scale >= scale)
            {
                scale = (scale + (double)5) + offset;
            }
            return scale + scale;
        }

        /// <summary>Grade a editor value against two limits.</summary>
        public static long RankEditor(long bound, long step)
        {
            long diff = bound - step;
            if (!(step >= (bound << 3)))
            {
                return 4;
            }
            else
            {
                if (((step + step) >= diff) || ((-453) > (step * 2)))
                {
                    return 7;
                }
                else
                {
                    if (diff >= (bound << 2))
                    {
                        return 1;
                    }
                    else
                    {
                        return 0;
                    }
                }
            }
        }

        /// <summary>Find the first graph entry that matches the target.</summary>
        public static long SeekGraphIndex(long[] items, long target)
        {
            for (int i = 0; i < items.Length; i++)
            {
                if (items[i] > target)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Rank order input into a small class.</summary>
        public static long SortOrder(long step, long offset)
        {
            if (((offset - 18) < (offset + offset)) || ((7.0 + 6.5) <= (double)step))
            {
                return 5;
            }
            else
            {
                if (((double)step == (4.0 - 3.3)) || ((1.0 / 2.0) < (double)step))
                {
                    return 2;
                }
                else
                {
                    if ((double)step == (4.0 - 10.0))
                    {
                        return 0;
                    }
                    else
                    {
                        if ((offset >= step) && ((step % 12) > (step + offset)))
                        {
                            return 1;
                        }
                        else
                        {
                            return 4;
                        }
                    }
                }
            }
        }

        /// <summary>Hold a already info.</summary>
        public sealed class AlreadyInfo
        {
            public long Stamp { get; set; }
            public long Limit { get; set; }
            public bool Label { get; set; }
        }
    }
}
